'use client';
/**
 * The hero's product window as a lit object: it leans toward the pointer (≤ 2.6°, the tilt-parallax-card technique
 * with one token spring per channel), a highlight and a lit border ring follow the pointer (spotlight-border-card),
 * and it lifts on hover with a two-layer shadow (tight contact + wide ambient, light from the top-left). While a
 * button is held inside it the lean eases off, so the target never moves under a press. Scrolling drifts it a little
 * slower than the copy. All of it is custom properties on one element, written from a useRafLoop that sleeps.
 */
import { useEffect, useRef, useState, type PointerEvent, type ReactNode } from 'react';
import { createSequence, spring as SPRING, springToLinear, useRafLoop, useScrollProgress } from '../../../motion';
import styles from './styles.module.css';

type Channel = 'rx' | 'ry' | 'gx' | 'gy' | 'glow' | 'lift';
const CHANNELS: readonly Channel[] = ['rx', 'ry', 'gx', 'gy', 'glow', 'lift'];
const REST: Record<Channel, number> = { rx: 0, ry: 0, gx: 18, gy: 8, glow: 0, lift: 0 };
const MAX_TILT = 2.6;
const SETTLE = springToLinear(SPRING.settle);

export function HeroWindow({ reduced, children }: { reduced: boolean; children: ReactNode }) {
  const visual = useRef<HTMLDivElement>(null);
  const scene = useRef<HTMLDivElement>(null);
  const sim = useRef({ x: { ...REST }, v: Object.fromEntries(CHANNELS.map((c) => [c, 0])) as Record<Channel, number>, t: { ...REST } });
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);
  const pressing = useRef(false);
  const last = useRef<{ px: number; py: number } | null>(null);
  const p0 = useRef<number | null>(null);

  const write = () => {
    const el = scene.current;
    if (!el) return;
    for (const c of CHANNELS) el.style.setProperty(`--${c}`, sim.current.x[c].toFixed(3));
  };
  const aim = (t: Partial<Record<Channel, number>>) => {
    Object.assign(sim.current.t, t);
    if (!runningRef.current) { runningRef.current = true; setRunning(true); }
  };

  useEffect(() => {
    if (!reduced) return;
    sim.current.x = { ...REST };
    sim.current.t = { ...REST };
    write();
  }, [reduced]);

  useRafLoop(scene, (dt) => {
    const s = sim.current, c = SPRING.settle;
    const n = Math.max(1, Math.ceil(dt * 240)), h = dt / n;
    let rest = true;
    for (const k of CHANNELS) {
      for (let i = 0; i < n; i++) { s.v[k] += ((-c.stiffness * (s.x[k] - s.t[k]) - c.damping * s.v[k]) / c.mass) * h; s.x[k] += s.v[k] * h; }
      const eps = k === 'gx' || k === 'gy' ? 0.2 : 0.004;
      if (Math.abs(s.x[k] - s.t[k]) > eps || Math.abs(s.v[k]) > eps * 4) rest = false;
    }
    write();
    if (rest) { runningRef.current = false; setRunning(false); }
  }, running && !reduced);

  // Scroll: the window drifts up a little slower than the page (one layer, ≤ 48 px over the whole hero).
  useScrollProgress(visual, (p) => {
    if (p0.current === null) p0.current = p;
    scene.current?.style.setProperty('--drift', `${((p - p0.current) * -48).toFixed(2)}px`);
  }, { enabled: !reduced });

  // Entrance: the window rises and settles while its shadow spreads under it (secondary action).
  useEffect(() => {
    const el = scene.current;
    if (reduced || !el) return;
    const seq = createSequence()
      .add(el.querySelector('[data-win]'), [{ translate: '0 30px', rotate: 'x 5deg' }, { translate: '0 0', rotate: 'x 0deg' }], { at: 140, duration: SETTLE.duration * 1.2, easing: SETTLE.easing, fill: 'backwards' })
      .add(el.querySelectorAll('[data-shade]'), [{ opacity: 0, scale: '0.9' }, { opacity: 1, scale: '1' }], { at: 140, duration: SETTLE.duration * 1.2, easing: SETTLE.easing, fill: 'backwards' });
    void seq.play();
    return () => seq.cancel();
  }, [reduced]);

  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    if (reduced || e.pointerType === 'touch') return;
    const r = e.currentTarget.getBoundingClientRect();
    if (r.width < 1 || r.height < 1) return;
    const px = Math.min(1, Math.max(0, (e.clientX - r.left) / r.width));
    const py = Math.min(1, Math.max(0, (e.clientY - r.top) / r.height));
    last.current = { px, py };
    const k = pressing.current ? 0.25 : 1;
    aim({ rx: (0.5 - py) * 2 * MAX_TILT * k, ry: (px - 0.5) * 2 * MAX_TILT * k, gx: px * 100, gy: py * 100, glow: 1, lift: 1 });
  };
  const onLeave = () => { last.current = null; pressing.current = false; if (!reduced) aim(REST); };
  const onDown = () => { pressing.current = true; if (last.current && !reduced) aim({ rx: sim.current.t.rx * 0.25, ry: sim.current.t.ry * 0.25 }); };
  const onUp = () => { pressing.current = false; };

  return (
    <div ref={visual} className={styles.heroVisual} onPointerMove={onMove} onPointerLeave={onLeave} onPointerDownCapture={onDown} onPointerUpCapture={onUp}>
      <div ref={scene} className={styles.scene}>
        <span className={styles.shadeAmbient} data-shade="" aria-hidden="true" />
        <span className={styles.shadeContact} data-shade="" aria-hidden="true" />
        <div className={styles.tiltWin} data-win="">
          {children}
          <span className={styles.glare} aria-hidden="true" />
        </div>
      </div>
    </div>
  );
}

'use client';
import { useCallback, useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react';
import { flushSync } from 'react-dom';
import { cssEase, duration as D, spring as SPRING, springToLinear, useElementSize, useIsomorphicLayoutEffect, useRafLoop } from '../../../motion';
import { DELIVERIES, FAILED, INBOX_URL, secondsOf, type Delivery } from './content';
import styles from './styles.module.css';

const POP = springToLinear(SPRING.pop);
const DAY = 86400;
/** Deliveries in time order (the list shows them newest first). */
const BY_TIME = [...DELIVERIES].sort((a, b) => secondsOf(a.at) - secondsOf(b.at));
const hhmm = (sec: number) => { const s = Math.max(0, Math.min(DAY - 1, Math.round(sec))); return `${String(Math.floor(s / 3600)).padStart(2, '0')}:${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}`; };
const wait = (ms: number) => new Promise<void>((r) => window.setTimeout(r, ms));

/** Minimal JSON tokeniser for the payload view (keys, strings, numbers, punctuation). */
export function Json({ text }: { text: string }) {
  const out: ReactNode[] = [];
  const re = /("(?:\\.|[^"\\])*")(\s*:)?|(-?\d+(?:\.\d+)?)|(true|false|null)|([{}[\],])/g;
  let last = 0, m: RegExpExecArray | null, k = 0;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index));
    if (m[1] && m[2]) out.push(<span key={k++} className={styles.jKey}>{m[1]}</span>, m[2]);
    else if (m[1]) out.push(<span key={k++} className={styles.jStr}>{m[1]}</span>);
    else if (m[3] || m[4]) out.push(<span key={k++} className={styles.jNum}>{m[3] ?? m[4]}</span>);
    else out.push(<span key={k++} className={styles.jPunct}>{m[5]}</span>);
    last = re.lastIndex;
  }
  if (last < text.length) out.push(text.slice(last));
  return <>{out}</>;
}

export function StatusChip({ status, chip }: { status: number; chip?: string }) {
  const ok = status < 400;
  return <span className={styles.status} data-ok={ok} data-chip={chip}>{status}<span className={styles.srOnly}>{ok ? ' OK' : ' error'}</span></span>;
}

interface Attempt { status: number; ms: number; label: string }

/* ── Yesterday, as a strip you can scrub ───────────────────────────────────
   Each delivery is a tick at its time of day (height = response time, colour = status). The playhead is a spring:
   drag it and the delivery under it is selected live; let go and it keeps its velocity, then settles on the
   nearest delivery. The list rows are its twin, and the arrow keys step between deliveries. */
function Timeline({ selected, onSelect, statusOf, reduced }: { selected: Delivery; onSelect: (id: string) => void; statusOf: (d: Delivery) => number; reduced: boolean }) {
  const uid = useId();
  const track = useRef<HTMLDivElement>(null);
  const head = useRef<HTMLDivElement>(null);
  const label = useRef<HTMLSpanElement>(null);
  const size = useElementSize(track);
  const sim = useRef({ x: reduced ? secondsOf(selected.at) : 0, v: 0, target: secondsOf(selected.at) });
  const drag = useRef<{ id: number } | null>(null);
  const last = useRef(selected.id);
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);

  const write = useCallback(() => {
    const el = head.current;
    if (!el || size.width < 1) return;
    el.style.transform = `translateX(${((sim.current.x / DAY) * size.width).toFixed(2)}px)`;
    if (label.current) label.current.textContent = hhmm(sim.current.x);
  }, [size.width]);
  const wake = () => { if (!runningRef.current) { runningRef.current = true; setRunning(true); } };
  useEffect(() => { write(); }, [write]);

  // The list (or the keyboard) chose a delivery: glide there.
  useEffect(() => {
    if (drag.current) return;
    last.current = selected.id;
    sim.current.target = secondsOf(selected.at);
    if (reduced) { sim.current.x = sim.current.target; sim.current.v = 0; write(); } else wake();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected.id, reduced]);

  const nearest = (sec: number) => BY_TIME.reduce((b, d) => (Math.abs(secondsOf(d.at) - sec) < Math.abs(secondsOf(b.at) - sec) ? d : b), BY_TIME[0]);

  useRafLoop(track, (dt) => {
    const s = sim.current, held = !!drag.current;
    const c = held ? SPRING.press : SPRING.release;
    const n = Math.max(1, Math.ceil(dt * 240)), h = dt / n;
    for (let i = 0; i < n; i++) { s.v += ((-c.stiffness * (s.x - s.target) - c.damping * s.v) / c.mass) * h; s.x += s.v * h; }
    write();
    if (held) { const d = nearest(s.x); if (d.id !== last.current) { last.current = d.id; onSelect(d.id); } }
    else if (Math.abs(s.x - s.target) < 8 && Math.abs(s.v) < 30) { s.x = s.target; s.v = 0; write(); runningRef.current = false; setRunning(false); }
  }, running && !reduced);

  const timeAt = (clientX: number) => {
    const r = track.current?.getBoundingClientRect();
    return r && r.width > 0 ? Math.max(0, Math.min(DAY - 1, ((clientX - r.left) / r.width) * DAY)) : sim.current.x;
  };
  const onDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    drag.current = { id: e.pointerId };
    head.current?.focus({ preventScroll: true });
    sim.current.target = timeAt(e.clientX);
    if (reduced) { sim.current.x = sim.current.target; write(); const d = nearest(sim.current.x); if (d.id !== last.current) { last.current = d.id; onSelect(d.id); } } else wake();
  };
  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current?.id !== e.pointerId) return;
    sim.current.target = timeAt(e.clientX);
    if (reduced) { sim.current.x = sim.current.target; write(); const d = nearest(sim.current.x); if (d.id !== last.current) { last.current = d.id; onSelect(d.id); } }
  };
  const onUp = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current?.id !== e.pointerId) return;
    drag.current = null;
    // Keep the throw: project the release along its velocity, then settle on the delivery nearest to that point.
    const s = sim.current;
    const d = nearest(s.x + s.v * 0.2);
    last.current = d.id;
    s.target = secondsOf(d.at);
    onSelect(d.id);
    if (reduced) { s.x = s.target; write(); } else wake();
  };
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const i = BY_TIME.findIndex((d) => d.id === selected.id);
    const to = e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === 'PageDown' ? i - 1
      : e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === 'PageUp' ? i + 1
        : e.key === 'Home' ? 0 : e.key === 'End' ? BY_TIME.length - 1 : null;
    if (to === null) return;
    e.preventDefault();
    const d = BY_TIME[Math.max(0, Math.min(BY_TIME.length - 1, to))];
    if (d.id !== selected.id) onSelect(d.id);
  };

  const st = statusOf(selected);
  return (
    <div className={styles.timeline}>
      <div className={styles.tlHead}>
        <span id={`${uid}tl`}>Yesterday · {DELIVERIES.length} deliveries</span>
        <span className={styles.tlHint} aria-hidden="true">Tick height = response time</span>
      </div>
      <div ref={track} className={styles.tlTrack} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
        {[0, 6, 12, 18].map((h) => <span key={h} className={styles.tlHour} style={{ left: `${(h / 24) * 100}%`, translate: h ? undefined : '0 0' }} aria-hidden="true">{String(h).padStart(2, '0')}</span>)}
        {BY_TIME.map((d, i) => {
          const status = statusOf(d);
          return (
            <span key={d.id} className={styles.tlTick} data-ok={status < 400} data-on={d.id === selected.id || undefined} data-chip={d.id}
              style={{ left: `${(secondsOf(d.at) / DAY) * 100}%`, height: `${Math.round(22 + (d.ms / 320) * 70)}%`, '--i': i } as CSSProperties} aria-hidden="true" />
          );
        })}
        <div ref={head} className={styles.playhead} role="slider" tabIndex={0} aria-labelledby={`${uid}tl`}
          aria-valuemin={0} aria-valuemax={DAY - 1} aria-valuenow={secondsOf(selected.at)}
          aria-valuetext={`${selected.at}, ${selected.event}, ${st} ${st < 400 ? 'OK' : 'error'}`} onKeyDown={onKey}>
          <span className={styles.phLine} aria-hidden="true" />
          <span className={styles.phKnob} aria-hidden="true"><span ref={label}>{hhmm(sim.current.x)}</span></span>
        </div>
      </div>
    </div>
  );
}

export function Inbox({ reduced }: { reduced: boolean }) {
  const uid = useId();
  const root = useRef<HTMLDivElement>(null);
  const body = useRef<HTMLDivElement>(null);
  const list = useRef<HTMLUListElement>(null);
  const rowInd = useRef<HTMLSpanElement>(null);
  const detail = useRef<HTMLDivElement>(null);
  const code = useRef<HTMLPreElement>(null);
  const path = useRef<SVGPathElement>(null);
  const packet = useRef<HTMLSpanElement>(null);
  const endpoint = useRef<HTMLSpanElement>(null);
  const burst = useRef<HTMLSpanElement>(null);
  const [selectedId, setSelectedId] = useState(FAILED.id);
  const [attempts, setAttempts] = useState<Record<string, Attempt[]>>({});
  const [busy, setBusy] = useState(false);
  const [said, setSaid] = useState('');
  const anims = useRef(new Set<Animation>());
  const alive = useRef(true);
  useEffect(() => { alive.current = true; const set = anims.current; return () => { alive.current = false; for (const a of set) a.cancel(); }; }, []);
  const track = (a: Animation | undefined | null) => { if (!a) return a; anims.current.add(a); const off = () => anims.current.delete(a); a.finished.then(off, off); return a; };

  const selected = DELIVERIES.find((d) => d.id === selectedId) ?? FAILED;
  const list_ = attempts[selected.id] ?? [];
  const latest = (d: Delivery) => (attempts[d.id] ?? []).at(-1)?.status ?? d.status;
  const fixed = list_.some((a) => a.status < 400);

  // The selection highlight slides between rows (measured once per change, moved with a transform).
  useIsomorphicLayoutEffect(() => {
    const row = list.current?.querySelector<HTMLElement>(`[data-row="${selected.id}"]`);
    const ind = rowInd.current;
    if (!row || !ind) return;
    ind.style.transform = `translateY(${row.offsetTop}px)`;
    ind.style.height = `${row.offsetHeight}px`;
  }, [selected.id]);
  // The payload view eases in on every change of delivery (scrubbing reads as flipping through the day).
  const first = useRef(true);
  useIsomorphicLayoutEffect(() => {
    if (first.current) { first.current = false; return; }
    if (reduced) return;
    for (const el of [detail.current, code.current]) track(el?.animate([{ opacity: 0.35, transform: 'translateY(5px)' }, { opacity: 1, transform: 'none' }], { duration: D.base, easing: cssEase('emphasized') }));
  }, [selected.id]);

  const select = useCallback((id: string) => setSelectedId(id), []);

  /** The signature replay: the payload leaves its row along a drawn path, reaches the endpoint, and the 500 springs to 200. */
  const replay = async () => {
    if (busy) return;
    const id = selected.id;
    setBusy(true);
    setSaid('Replaying to localhost:3000…');
    const commit = () => {
      const a: Attempt = { status: 200, ms: 84, label: 'Replay to localhost:3000' };
      flushSync(() => setAttempts((m) => ({ ...m, [id]: [...(m[id] ?? []), a] })));
      setBusy(false);
      setSaid(`Replay finished: 200 OK in ${a.ms} milliseconds (simulated).`);
    };
    const b = body.current, p = path.current, pk = packet.current, ep = endpoint.current;
    const fromEl = root.current?.querySelector<HTMLElement>(`[data-row="${id}"] [data-chip]`);
    if (reduced || !b || !p || !pk || !ep || !fromEl || typeof pk.animate !== 'function') {
      await wait(350);
      if (!alive.current) return;
      commit();
      return;
    }
    const br = b.getBoundingClientRect(), fr = fromEl.getBoundingClientRect(), tr = ep.getBoundingClientRect();
    const sx = fr.right - br.left + 4, sy = fr.top + fr.height / 2 - br.top;
    const ex = tr.left - br.left + 12, ey = tr.top + tr.height / 2 - br.top;
    // An arc, not a line: the path rises out of the row and drops onto the endpoint.
    const lift = Math.max(60, Math.abs(ex - sx) * 0.35);
    const d = `M${sx.toFixed(1)} ${sy.toFixed(1)} C${(sx + (ex - sx) * 0.35).toFixed(1)} ${(Math.min(sy, ey) - lift).toFixed(1)}, ${(ex - (ex - sx) * 0.15).toFixed(1)} ${(Math.min(sy, ey) - lift * 0.6).toFixed(1)}, ${ex.toFixed(1)} ${ey.toFixed(1)}`;
    p.setAttribute('d', d);
    pk.style.offsetPath = `path('${d}')`;
    b.dataset.replaying = '';
    track(p.animate([{ strokeDashoffset: 1, opacity: 1 }, { strokeDashoffset: 0, opacity: 1 }], { duration: D.slow, easing: cssEase('emphasized'), fill: 'forwards' }));
    const travel = track(pk.animate([
      { offsetDistance: '0%', transform: 'scale(0.4)', opacity: 0 },
      { offsetDistance: '6%', transform: 'scale(1.06)', opacity: 1, offset: 0.14 },
      { offsetDistance: '100%', transform: 'scale(0.8)', opacity: 1 },
    ], { duration: 820, delay: 120, easing: cssEase('inOut'), fill: 'forwards' }));
    try { await travel?.finished; } catch { return; }
    if (!alive.current) return;
    // Arrival: the endpoint takes the hit, the chips squash, the answer comes back 200 and springs out.
    track(ep.animate([{ transform: 'scale(1.1)' }, { transform: 'none' }], { duration: POP.duration, easing: POP.easing }));
    track(pk.animate([{ opacity: 1, transform: 'scale(0.8)' }, { opacity: 0, transform: 'scale(0.3)' }], { duration: D.fast, easing: cssEase('exit'), fill: 'forwards' }));
    const chips = () => [...(root.current?.querySelectorAll<HTMLElement>(`[data-chip="${id}"]`) ?? [])];
    const squash = chips().map((c) => track(c.animate([{ transform: 'none' }, { transform: 'scale(0.55, 0.8)', opacity: 0.25 }], { duration: 110, easing: cssEase('exit'), fill: 'forwards' })));
    await wait(110);
    if (!alive.current) return;
    commit();
    for (const s of squash) s?.cancel();
    for (const c of chips()) track(c.animate([{ transform: 'scale(0.55, 0.8)', opacity: 0.25 }, { transform: 'none', opacity: 1 }], { duration: POP.duration, easing: POP.easing }));
    const resp = root.current?.querySelector<HTMLElement>(`[data-resp] [data-chip="${id}"]`);
    const bu = burst.current;
    if (resp && bu) {
      const rr = resp.getBoundingClientRect();
      bu.style.left = `${(rr.left + rr.width / 2 - br.left).toFixed(1)}px`;
      bu.style.top = `${(rr.top + rr.height / 2 - br.top).toFixed(1)}px`;
      [...bu.children].forEach((ray, i) => {
        const ang = (i / bu.children.length) * 360 + 22.5;
        track((ray as HTMLElement).animate([
          { transform: `rotate(${ang}deg) translateX(10px) scaleX(0.2)`, opacity: 0 },
          { transform: `rotate(${ang}deg) translateX(18px) scaleX(1)`, opacity: 1, offset: 0.35 },
          { transform: `rotate(${ang}deg) translateX(30px) scaleX(0.3)`, opacity: 0 },
        ], { duration: D.slow, easing: cssEase('emphasized'), fill: 'forwards' }));
      });
    }
    track(p.animate([{ strokeDashoffset: 0, opacity: 1 }, { strokeDashoffset: -1, opacity: 0.2 }], { duration: D.moderate, delay: D.fast, easing: cssEase('exit'), fill: 'forwards' }))?.finished.then(() => { delete b.dataset.replaying; }, () => {});
  };

  return (
    <div ref={root} className={styles.window} role="group" aria-label="Tarn inbox, sample data">
      <div className={styles.winBar}>
        <span className={styles.winDots} aria-hidden="true"><i /><i /><i /></span>
        <span className={styles.winTitle}>payments</span>
        <span className={styles.winUrl}>{INBOX_URL}</span>
        <span className={styles.sampleTag}>Sample data</span>
      </div>
      <Timeline selected={selected} onSelect={select} statusOf={latest} reduced={reduced} />
      <div ref={body} className={styles.winBody}>
        <div className={styles.listWrap}>
        <span ref={rowInd} className={styles.rowInd} aria-hidden="true" />
        <ul ref={list} className={styles.deliveries} aria-label="Deliveries">
          {DELIVERIES.map((d) => (
            <li key={d.id} data-row={d.id}>
              <button type="button" className={styles.delivery} aria-pressed={selected.id === d.id} onClick={() => select(d.id)}>
                <StatusChip status={latest(d)} chip={d.id} />
                <span className={styles.dEvent}>{d.event}</span>
                <span className={styles.dMeta}>{d.source} · {d.at}</span>
              </button>
            </li>
          ))}
        </ul>
        </div>
        <div className={styles.detail}>
          <div ref={detail}>
            <p className={styles.reqLine}><span className={styles.method}>POST</span> /hooks/{selected.source} <span className={styles.dimText}>· {selected.id} · yesterday {selected.at}</span></p>
            <p className={styles.respLine} data-resp="">
              <StatusChip status={latest(selected)} chip={selected.id} />{' '}
              <span>{fixed ? 'Replay answered 200 OK in 84 ms (simulated). The original 500 stays in the history.' : selected.status >= 400 ? 'Your endpoint answered 500: TypeError, lines.map is not a function' : `Delivered in ${selected.ms} ms`}</span>
            </p>
          </div>
          <p className={styles.replayTarget}>
            <span className={styles.fLabel}>Target</span>
            <span ref={endpoint} className={styles.endpoint}><span className={styles.endDot} aria-hidden="true" />localhost:3000<span className={styles.dimText}>/hooks/{selected.source}</span></span>
          </p>
          <div className={styles.replayRow}>
            <button type="button" className={styles.replayBtn} onClick={() => void replay()} aria-busy={busy || undefined} aria-describedby={`${uid}said`}>
              <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M2.5 8a5.5 5.5 0 1 0 1.7-4" /><path d="M2.5 2.5v3h3" /></svg>
              {busy ? 'Replaying…' : fixed ? 'Replay again' : 'Replay to localhost:3000'}
            </button>
            <p id={`${uid}said`} className={styles.said} role="status">{said || (selected.status >= 400 && !fixed ? 'Fixed the bug? Replay the exact delivery that failed.' : 'Replay any delivery, as many times as you need.')}</p>
          </div>
          {list_.length ? (
            <ol className={styles.attempts} aria-label="History">
              <li><StatusChip status={selected.status} /> Original delivery · {selected.ms} ms</li>
              {list_.map((a, i) => <li key={i} data-new={i === list_.length - 1 || undefined}><StatusChip status={a.status} /> {a.label} · {a.ms} ms <span className={styles.dimText}>(simulated)</span></li>)}
            </ol>
          ) : null}
          <pre ref={code} className={styles.code}><code><Json text={selected.body} /></code></pre>
        </div>
        <svg className={styles.flight} aria-hidden="true" focusable="false"><path ref={path} pathLength={1} /></svg>
        <span ref={packet} className={styles.packet} aria-hidden="true">{'{ }'} evt</span>
        <span ref={burst} className={styles.burst} aria-hidden="true">{Array.from({ length: 8 }, (_, i) => <i key={i} />)}</span>
      </div>
    </div>
  );
}

'use client';
import { useEffect, useId, useRef, useState, type KeyboardEvent, type ReactNode, type RefObject } from 'react';
import { spring as SPRING, useIsomorphicLayoutEffect, useRafLoop } from '../../../motion';
import { FAILED, FAQ, INBOX_URL, OVERAGE, PASSED, PLANS, TARGETS, formatUsd, type Target } from './content';
import { Json, StatusChip } from './Inbox';
import { Ticker } from './Ticker';
import styles from './styles.module.css';

/* ── Morphing indicator: measured once per change, moved with a CSS transform (no layout animation library) ── */
export function useIndicator(list: RefObject<HTMLElement | null>, index: number) {
  const [box, setBox] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  const [ready, setReady] = useState(false);
  useIsomorphicLayoutEffect(() => {
    const el = list.current;
    if (!el) return;
    const measure = () => {
      const it = el.querySelectorAll<HTMLElement>('[data-ind]')[index];
      setBox(it ? { x: it.offsetLeft, y: it.offsetTop, w: it.offsetWidth, h: it.offsetHeight } : null);
    };
    measure();
    const raf = requestAnimationFrame(() => setReady(true));
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : null;
    ro?.observe(el);
    return () => { cancelAnimationFrame(raf); ro?.disconnect(); };
  }, [list, index]);
  return { box, ready };
}

export function Indicator({ state, className }: { state: ReturnType<typeof useIndicator>; className?: string }) {
  const { box, ready } = state;
  return (
    <span aria-hidden="true" className={`${styles.ind} ${className ?? ''}`} data-ready={ready || undefined}
      style={box ? { transform: `translate(${box.x}px, ${box.y}px)`, width: box.w, height: box.h } : { opacity: 0 }} />
  );
}

/* ── Scroll reveal: content is visible by default; only hidden while JS waits for it to enter ── */
export function useReveal(enabled: boolean) {
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const items = Array.from(el.querySelectorAll<HTMLElement>('[data-reveal]'));
    if (!enabled || typeof IntersectionObserver === 'undefined') { for (const i of items) i.dataset.reveal = 'in'; return; }
    for (const i of items) if (i.getBoundingClientRect().top > window.innerHeight) i.dataset.reveal = 'wait';
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) if (e.isIntersecting) { (e.target as HTMLElement).dataset.reveal = 'in'; io.unobserve(e.target); }
    }, { threshold: 0.2 });
    for (const i of items) io.observe(i);
    return () => io.disconnect();
  }, [enabled]);
  return root;
}

/* ── Magnetic pull (the hero CTA only): the magnetic-button technique on this page's button ──
   A precise pointer within FIELD px of the button draws it in (capped with tanh, fading to zero at the field's edge);
   the label floats a little further than the body. Springs from the tokens; the loop sleeps once both are home. */
const FIELD = 76;
function useMagnet(anchor: RefObject<HTMLSpanElement | null>, body: RefObject<HTMLButtonElement | null>, label: RefObject<HTMLSpanElement | null>, enabled: boolean) {
  const sim = useRef({ bx: 0, bv: 0, by: 0, byv: 0, lx: 0, lv: 0, ly: 0, lyv: 0, tx: 0, ty: 0 });
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);
  useEffect(() => {
    if (!enabled) return;
    const fine = window.matchMedia?.('(hover: hover) and (pointer: fine)').matches;
    if (!fine) return;
    const onMove = (e: globalThis.PointerEvent) => {
      const r = anchor.current?.getBoundingClientRect();
      if (!r) return;
      const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);
      const edge = Math.max(0, Math.hypot(Math.max(0, Math.abs(dx) - r.width / 2), Math.max(0, Math.abs(dy) - r.height / 2)));
      const s = sim.current;
      if (edge < FIELD) {
        const w = 1 - Math.min(1, edge / FIELD), lim = r.height * 0.42;
        s.tx = lim * Math.tanh((dx * 0.26 * w * w) / lim);
        s.ty = lim * Math.tanh((dy * 0.26 * w * w) / lim);
      } else { s.tx = 0; s.ty = 0; }
      if ((s.tx || s.ty || s.bx || s.by) && !runningRef.current) { runningRef.current = true; setRunning(true); }
    };
    window.addEventListener('pointermove', onMove, { passive: true });
    return () => {
      window.removeEventListener('pointermove', onMove);
      if (body.current) body.current.style.translate = '';
      if (label.current) label.current.style.translate = '';
    };
  }, [enabled, anchor, body, label]);
  useRafLoop(anchor, (dt) => {
    const s = sim.current, c = s.tx || s.ty ? SPRING.settle : SPRING.release;
    const n = Math.max(1, Math.ceil(dt * 240)), h = dt / n;
    for (let i = 0; i < n; i++) {
      s.bv += ((-c.stiffness * (s.bx - s.tx) - c.damping * s.bv) / c.mass) * h; s.bx += s.bv * h;
      s.byv += ((-c.stiffness * (s.by - s.ty) - c.damping * s.byv) / c.mass) * h; s.by += s.byv * h;
      s.lv += ((-c.stiffness * (s.lx - s.tx * 0.4) - c.damping * s.lv) / c.mass) * h; s.lx += s.lv * h;
      s.lyv += ((-c.stiffness * (s.ly - s.ty * 0.4) - c.damping * s.lyv) / c.mass) * h; s.ly += s.lyv * h;
    }
    if (body.current) body.current.style.translate = `${s.bx.toFixed(2)}px ${s.by.toFixed(2)}px`;
    if (label.current) label.current.style.translate = `${s.lx.toFixed(2)}px ${s.ly.toFixed(2)}px`;
    const home = !s.tx && !s.ty && Math.abs(s.bx) + Math.abs(s.by) + Math.abs(s.lx) + Math.abs(s.ly) < 0.05 && Math.abs(s.bv) + Math.abs(s.byv) < 0.2;
    if (home) {
      Object.assign(s, { bx: 0, bv: 0, by: 0, byv: 0, lx: 0, lv: 0, ly: 0, lyv: 0 });
      if (body.current) body.current.style.translate = '';
      if (label.current) label.current.style.translate = '';
      runningRef.current = false;
      setRunning(false);
    }
  }, running && enabled);
}

/* ── The single primary action, repeated with the same label ─────────── */
export function Cta({ label = 'Create a free inbox', note = 'Free up to 10,000 deliveries a month. No card.', magnetic = false, reduced = false }: { label?: string; note?: string; magnetic?: boolean; reduced?: boolean }) {
  const [said, setSaid] = useState(false);
  const anchor = useRef<HTMLSpanElement>(null);
  const body = useRef<HTMLButtonElement>(null);
  const face = useRef<HTMLSpanElement>(null);
  useMagnet(anchor, body, face, magnetic && !reduced);
  return (
    <div className={styles.ctaWrap}>
      <span ref={anchor} className={styles.ctaAnchor}>
        <button ref={body} type="button" className={styles.primary} onClick={() => setSaid(true)}><span ref={face} className={styles.ctaFace}>{label}</span></button>
      </span>
      <p className={styles.ctaNote} aria-live="polite">{said ? 'Demo only: sign-up would start here with an email and a password, nothing else.' : note}</p>
    </div>
  );
}

/* ── How it works: capture → inspect → replay, each a working fragment ── */
const STEPS = ['Capture', 'Inspect', 'Replay'] as const;

export function HowItWorks({ reduced }: { reduced: boolean }) {
  const uid = useId();
  const [tab, setTab] = useState(0);
  const list = useRef<HTMLDivElement>(null);
  const tabs = useRef<(HTMLButtonElement | null)[]>([]);
  const ind = useIndicator(list, tab);
  const onKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    const to = e.key === 'ArrowRight' ? (i + 1) % 3 : e.key === 'ArrowLeft' ? (i + 2) % 3 : e.key === 'Home' ? 0 : e.key === 'End' ? 2 : null;
    if (to === null) return;
    e.preventDefault();
    setTab(to);
    tabs.current[to]?.focus();
  };
  return (
    <div className={styles.how}>
      <div ref={list} className={styles.tabs} role="tablist" aria-label="How Tarn works">
        <Indicator state={ind} />
        {STEPS.map((s, i) => (
          <button key={s} ref={(el) => { tabs.current[i] = el; }} type="button" role="tab" data-ind id={`${uid}t${i}`} aria-selected={tab === i}
            aria-controls={`${uid}p${i}`} tabIndex={tab === i ? 0 : -1} className={styles.tab} onClick={() => setTab(i)} onKeyDown={(e) => onKey(e, i)}>
            <span className={styles.tabNum} aria-hidden="true">{i + 1}</span>{s}
          </button>
        ))}
      </div>
      <div id={`${uid}p0`} role="tabpanel" aria-labelledby={`${uid}t0`} hidden={tab !== 0} className={styles.panel}><Capture reduced={reduced} /></div>
      <div id={`${uid}p1`} role="tabpanel" aria-labelledby={`${uid}t1`} hidden={tab !== 1} className={styles.panel}><Inspect /></div>
      <div id={`${uid}p2`} role="tabpanel" aria-labelledby={`${uid}t2`} hidden={tab !== 2} className={styles.panel}><Replay reduced={reduced} /></div>
    </div>
  );
}

function Capture({ reduced }: { reduced: boolean }) {
  const uid = useId();
  const [copied, setCopied] = useState<'idle' | 'ok' | 'manual'>('idle');
  const [events, setEvents] = useState<{ n: number; at: string }[]>([]);
  const field = useRef<HTMLInputElement>(null);
  const copy = async () => {
    try { await navigator.clipboard.writeText(INBOX_URL); setCopied('ok'); }
    catch { setCopied('manual'); field.current?.focus(); field.current?.select(); }
  };
  const send = () => setEvents((e) => [{ n: e.length + 1, at: new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) }, ...e].slice(0, 4));
  return (
    <div className={styles.panelGrid}>
      <div className={styles.panelCopy}>
        <h3 className={styles.panelTitle}>Give your provider one URL.</h3>
        <p>Every inbox has its own address. Paste it where your payments provider, shop or CRM asks for a webhook endpoint; Tarn answers 200 once a delivery is stored and keeps the raw bytes.</p>
      </div>
      <div className={styles.fragment}>
        <label htmlFor={`${uid}url`} className={styles.fLabel}>Webhook endpoint</label>
        <div className={styles.urlRow}>
          <input id={`${uid}url`} ref={field} className={styles.urlField} readOnly value={INBOX_URL} />
          <button type="button" className={styles.smallBtn} onClick={copy}>{copied === 'ok' ? 'Copied' : 'Copy'}</button>
        </div>
        <p className={styles.fHint} aria-live="polite">{copied === 'manual' ? 'Copying isn’t available here: the address is selected, copy it with your keyboard.' : copied === 'ok' ? 'Copied to the clipboard.' : 'Sample address (.example domains never resolve).'}</p>
        <button type="button" className={styles.smallBtn} onClick={send}>Send a test event</button>
        <ul className={styles.feed} aria-live="polite" aria-label="Received test events">
          {events.map((e) => (
            <li key={e.n} data-new={!reduced || undefined}><StatusChip status={200} /> <span className={styles.mono}>ping.test</span> <span className={styles.dimText}>stored at {e.at}</span></li>
          ))}
          {events.length === 0 ? <li className={styles.dimText}>No test events yet.</li> : null}
        </ul>
      </div>
    </div>
  );
}

function Inspect() {
  const ok = PASSED.body.split('\n');
  const bad = FAILED.body.split('\n');
  return (
    <div className={styles.panelGrid}>
      <div className={styles.panelCopy}>
        <h3 className={styles.panelTitle}>Compare the one that failed.</h3>
        <p>Pick two deliveries and Tarn lines them up. Here the failing invoice has three lines where every invoice that went through had one, which is the bug: the handler assumed a single line.</p>
      </div>
      <div className={styles.fragment}>
        <p className={styles.fLabel}>dlv_0192 <StatusChip status={200} /> → dlv_0193 <StatusChip status={500} /></p>
        <pre className={styles.diff}><code>
          {ok.map((line, i) => (line === bad[i]
            ? <span key={i} className={styles.dCtx}>{'  '}{line}{'\n'}</span>
            : <span key={i}><span className={styles.dDel}><span aria-hidden="true">− </span><span className={styles.srOnly}>passed: </span>{line.trimStart()}{'\n'}</span><span className={styles.dAdd} data-clue={/"lines"/.test(line) || undefined}><span aria-hidden="true">+ </span><span className={styles.srOnly}>failed: </span>{bad[i].trimStart()}{'\n'}</span></span>))}
        </code></pre>
      </div>
    </div>
  );
}

function Replay({ reduced }: { reduced: boolean }) {
  const uid = useId();
  const [target, setTarget] = useState<Target>('localhost');
  const [phase, setPhase] = useState<'idle' | 'confirm' | 'busy' | 'done'>('idle');
  const [result, setResult] = useState<string | null>(null);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  const t = TARGETS.find((x) => x.id === target) ?? TARGETS[0];
  const run = () => {
    setPhase('busy');
    timer.current = window.setTimeout(() => { setPhase('done'); setResult(`200 OK in ${target === 'localhost' ? 84 : 132} ms from ${t.label}`); }, reduced ? 350 : 900);
  };
  const press = () => { if (phase === 'busy') return; if (target === 'production' && phase !== 'confirm') { setPhase('confirm'); return; } run(); };
  return (
    <div className={styles.panelGrid}>
      <div className={styles.panelCopy}>
        <h3 className={styles.panelTitle}>Replay it where you fixed it.</h3>
        <p>Send the original bytes and headers to your laptop, staging or production. A replay is marked with an <code className={styles.mono}>X-Tarn-Replay</code> header so your logs can tell it apart.</p>
      </div>
      <div className={styles.fragment}>
        <fieldset className={styles.targets}>
          <legend className={styles.fLabel}>Replay dlv_0193 to</legend>
          {TARGETS.map((x) => (
            <label key={x.id} className={styles.target}>
              <input type="radio" name={`${uid}target`} checked={target === x.id} onChange={() => { setTarget(x.id); setPhase('idle'); setResult(null); }} />
              <span><span className={styles.targetName}>{x.label}</span><span className={styles.dimText}>{x.note}</span></span>
            </label>
          ))}
        </fieldset>
        {phase === 'confirm' ? (
          <div className={styles.confirm} role="alert">
            <p>Replay to <span className={styles.mono}>{t.url}</span>? Your production handler will run again for this invoice.</p>
            <div className={styles.confirmRow}>
              <button type="button" className={styles.dangerBtn} onClick={run}>Replay to production</button>
              <button type="button" className={styles.smallBtn} onClick={() => setPhase('idle')}>Cancel</button>
            </div>
          </div>
        ) : (
          <button type="button" className={styles.replayBtn} onClick={press} aria-busy={phase === 'busy' || undefined}>
            {phase === 'busy' ? 'Replaying…' : `Replay to ${t.label}`}
          </button>
        )}
        <p className={styles.fHint} role="status">{result ? <><StatusChip status={200} /> {result} <span className={styles.dimText}>(simulated)</span></> : ''}</p>
        {result ? <pre className={styles.code}><code><Json text={'{ "received": true, "invoice": "in_4Xa91" }'} /></code></pre> : null}
      </div>
    </div>
  );
}

/* ── Pricing ───────────────────────────────────────────────────────────── */
export function Pricing({ reduced }: { reduced: boolean }) {
  const uid = useId();
  const [period, setPeriod] = useState<'monthly' | 'yearly'>('monthly');
  const group = useRef<HTMLDivElement>(null);
  const ind = useIndicator(group, period === 'monthly' ? 0 : 1);
  const team = PLANS.find((p) => p.id === 'team') ?? PLANS[1];
  const monthsFree = Math.round((team.monthly * 12 - team.yearly) / team.monthly);
  const [said, setSaid] = useState('');
  const [picked, setPicked] = useState<string | null>(null);
  const choose = (p: 'monthly' | 'yearly') => {
    setPeriod(p);
    setSaid(p === 'yearly' ? `Showing yearly prices. Team is ${formatUsd(team.yearly / 12)} a month, billed ${formatUsd(team.yearly)} a year.` : `Showing monthly prices. Team is ${formatUsd(team.monthly)} a month.`);
  };
  return (
    <div className={styles.pricing}>
      <fieldset className={styles.billing}>
        <legend className={styles.srOnly}>Billing period</legend>
        <div ref={group} className={styles.billingTrack}>
          <Indicator state={ind} className={styles.billingInd} />
          {(['monthly', 'yearly'] as const).map((p) => (
            <label key={p} data-ind className={styles.billingOpt}>
              <input type="radio" name={`${uid}period`} value={p} checked={period === p} onChange={() => choose(p)} />
              <span>{p === 'monthly' ? 'Monthly' : 'Yearly'}</span>
              {p === 'yearly' ? <span className={styles.save}>{monthsFree} months free</span> : null}
            </label>
          ))}
        </div>
      </fieldset>
      <p className={styles.srOnly} role="status">{said}</p>
      <div className={styles.plans}>
        {PLANS.map((p) => {
          const perMonth = period === 'monthly' ? p.monthly : p.yearly / 12;
          const primary = !!p.recommended;
          return (
            <article key={p.id} className={styles.plan} data-recommended={primary || undefined} aria-labelledby={`${uid}${p.id}`}>
              {p.recommended ? <p className={styles.badge}>Recommended</p> : null}
              <h3 id={`${uid}${p.id}`} className={styles.planName}>{p.name}</h3>
              <p className={styles.forWhom}>{p.forWhom}</p>
              <p className={styles.priceLine}>
                <Ticker value={perMonth} format={(n) => formatUsd(n)} reduced={reduced} className={styles.amount} />
                <span className={styles.unit}>per workspace / month</span>
              </p>
              <p className={styles.billed}>{p.monthly === 0 ? 'Free, no card' : period === 'yearly' ? `Billed ${formatUsd(p.yearly)} yearly` : 'Billed monthly, cancel any time'}</p>
              <p className={styles.quota}>{p.quota}</p>
              <ul className={styles.features}>{p.features.map((f) => <li key={f}>{f}</li>)}</ul>
              {p.recommended ? <p className={styles.why}>{p.recommended}</p> : null}
              <button type="button" className={primary ? styles.primary : styles.secondary} onClick={() => setPicked(p.cta)}>{p.cta}</button>
            </article>
          );
        })}
      </div>
      <p className={styles.ctaNote} aria-live="polite">{picked ? `Demo only: “${picked}” would open sign-up here. Trials need no card and end without charging you.` : ''}</p>
      <p className={styles.overage}><strong>Over your quota?</strong> {OVERAGE} Prices are sample data in US dollars, excluding VAT where it applies.</p>
    </div>
  );
}

/* ── FAQ: the accordion-height-auto technique (grid rows 0fr → 1fr), with this page’s questions ── */
export function Faq() {
  const uid = useId();
  const [open, setOpen] = useState<number | null>(null);
  const btns = useRef<(HTMLButtonElement | null)[]>([]);
  const onKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    const last = FAQ.length - 1;
    const to = e.key === 'ArrowDown' ? (i === last ? 0 : i + 1) : e.key === 'ArrowUp' ? (i === 0 ? last : i - 1) : e.key === 'Home' ? 0 : e.key === 'End' ? last : null;
    if (to === null) return;
    e.preventDefault();
    btns.current[to]?.focus();
  };
  return (
    <div className={styles.faq}>
      {FAQ.map((f, i) => (
        <div key={f.q} className={styles.qItem} data-open={open === i || undefined}>
          <h3 className={styles.qHeading}>
            <button ref={(el) => { btns.current[i] = el; }} type="button" id={`${uid}q${i}`} aria-expanded={open === i} aria-controls={`${uid}a${i}`}
              className={styles.qBtn} onClick={() => setOpen(open === i ? null : i)} onKeyDown={(e) => onKey(e, i)}>
              <span>{f.q}</span>
              <span className={styles.qIcon} aria-hidden="true"><i /><i /></span>
            </button>
          </h3>
          <div id={`${uid}a${i}`} role="region" aria-labelledby={`${uid}q${i}`} className={styles.qPanel}>
            <div className={styles.qInner}>{f.a.map((p) => <p key={p}>{p}</p>)}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

export function Section({ id, label, title, intro, children, headingRef }: { id: string; label: string; title: ReactNode; intro?: ReactNode; children: ReactNode; headingRef?: (el: HTMLHeadingElement | null) => void }) {
  return (
    <section id={id} className={styles.section} aria-labelledby={`${id}-h`}>
      <div className={styles.sectionHead}>
        <p className={styles.kicker}>{label}</p>
        <h2 id={`${id}-h`} ref={headingRef} tabIndex={-1} className={styles.h2}>{title}</h2>
        {intro ? <p className={styles.intro}>{intro}</p> : null}
      </div>
      {children}
    </section>
  );
}

/* Tarn — an HTTP field notebook on paper.
   Headlines in Bricolage, every artefact (payloads, URLs, codes) in JetBrains Mono, one demo colour — "lake" teal —
   for strings and the brand mark, the signal colour only for the primary action. Rules, not cards, separate content;
   the product window is the single elevated object and bleeds off the right edge. */

.root {
  --tarn-lake: #0b6e75;
  /* Elevation is two shadows (tight contact + wide ambient), light from the top-left. */
  --sh-rest: 0 1px 1.5px rgb(20 18 12 / 0.18), 0 6px 14px -9px rgb(20 18 12 / 0.32);
  --sh-lift: 0 1px 1px rgb(20 18 12 / 0.12), 0 16px 28px -14px rgb(20 18 12 / 0.38);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 4px -2px rgb(20 18 12 / 0.32);
  --tarn-pad: 16px;
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  overflow-x: clip;
}
:global([data-theme='dark']) .root {
  --tarn-lake: #5fc2c9;
  --sh-rest: 0 1px 1.5px rgb(0 0 0 / 0.5), 0 6px 14px -9px rgb(0 0 0 / 0.75);
  --sh-lift: 0 1px 1px rgb(0 0 0 / 0.45), 0 18px 30px -14px rgb(0 0 0 / 0.85);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 4px -2px rgb(0 0 0 / 0.7);
}
@container (min-width: 900px) { .root { --tarn-pad: 40px; } }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.mono { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.9em; }
.dimText { color: var(--mk-ink-muted, #5c5a52); }

/* ── Nav ───────────────────────────────────────────────────────────────── */
.nav { position: sticky; top: 44px; z-index: 20; display: flex; align-items: center; gap: 16px; height: 60px; padding: 0 var(--tarn-pad); background: var(--mk-bg, #f3f0e8); border-bottom: 1px solid var(--mk-line, #11110f24); }
.brand { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; color: var(--mk-ink, #11110f); text-decoration: none; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-weight: 700; font-size: 1.3125rem; letter-spacing: -0.03em; }
.brand svg { width: 24px; height: 24px; fill: none; stroke: var(--tarn-lake); stroke-width: 2; stroke-linecap: round; }
.navLinks { display: none; margin-left: 20px; }
.navTrack { position: relative; }
.navList { display: flex; gap: 6px; margin: 0; padding: 0; list-style: none; }
.navLink { display: inline-flex; align-items: center; min-height: 40px; padding: 0 12px; color: var(--mk-ink, #11110f); text-decoration: none; font-size: 0.9375rem; font-weight: 500; border-radius: 6px; }
.navLink:hover { color: var(--mk-ink, #11110f); background: var(--mk-surface-2, #e9e5da); }
.navLink[aria-current] { font-weight: 650; }
.navInd { border-bottom: 2px solid var(--mk-ink, #11110f); }
.navEnd { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.menuBtn { min-height: 40px; padding: 0 16px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; background: transparent; color: var(--mk-ink, #11110f); font: 500 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; }
.navCta { display: none; align-items: center; min-height: 40px; padding: 0 16px; border-radius: 8px; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); font-weight: 600; font-size: 0.9375rem; text-decoration: none; }
.navCta { box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 1px 1.5px rgb(0 0 0 / 0.22), 0 6px 14px -8px color-mix(in oklab, var(--mk-signal, #bf2f09) 75%, #000); transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease), background-color var(--mk-duration-fast, 160ms); }
.navCta:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 88%, #000); transform: translateY(-1px); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 1px 1px rgb(0 0 0 / 0.14), 0 12px 20px -10px color-mix(in oklab, var(--mk-signal, #bf2f09) 80%, #000); }
.navCta:active { transform: translateY(1px) scale(0.97); box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.2), 0 0 0 rgb(0 0 0 / 0); transition-duration: var(--mk-duration-instant, 90ms); }
.menuBtn { transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease); }
.menuBtn:hover { transform: translateY(-1px); box-shadow: var(--sh-rest); }
.menuBtn:active { transform: scale(0.96); box-shadow: none; transition-duration: var(--mk-duration-instant, 90ms); }
.menu { position: absolute; top: 100%; left: 0; right: 0; padding: 4px var(--tarn-pad) 14px; background: var(--mk-bg, #f3f0e8); border-bottom: 1px solid var(--mk-line-strong, #11110f); }
.menu[hidden] { display: none; }
.menu ul { display: grid; margin: 0; padding: 0; list-style: none; }
.menu a { display: flex; align-items: center; min-height: 48px; border-bottom: 1px solid var(--mk-line, #11110f24); color: var(--mk-ink, #11110f); text-decoration: none; font-size: 1.0625rem; }
@container (min-width: 560px) { .navCta { display: inline-flex; } }
@container (min-width: 820px) { .navLinks { display: block; } .menuBtn, .menu { display: none; } }
.brand:focus-visible, .navLink:focus-visible, .navCta:focus-visible, .menuBtn:focus-visible, .menu a:focus-visible, .textLink:focus-visible, .footLinks a:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }

/* Shared measured indicator */
.ind { position: absolute; top: 0; left: 0; pointer-events: none; }
.ind[data-ready] { transition: transform var(--mk-duration-base, 240ms) var(--mk-ease-emphasized, ease), width var(--mk-duration-base, 240ms) var(--mk-ease-emphasized, ease), height var(--mk-duration-base, 240ms) var(--mk-ease-emphasized, ease), opacity var(--mk-duration-fast, 160ms); }
.root[data-reduced] .ind { transition: none; }

/* ── Buttons ───────────────────────────────────────────────────────────── */
/* Every press has depth: hover lifts (contact shadow tightens, ambient widens), press compresses within a frame,
   release springs back on a curve sampled from the press spring (springToLinear). */
.primary, .secondary {
  display: inline-flex; align-items: center; justify-content: center; min-height: 52px; padding: 0 22px; border-radius: 10px; cursor: pointer;
  font: 600 1rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); text-align: center;
}
.primary, .secondary, .smallBtn, .replayBtn, .dangerBtn {
  transition:
    transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), border-color var(--mk-duration-fast, 160ms);
}
.primary { border: 0; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.22), 0 1px 1.5px rgb(0 0 0 / 0.24), 0 8px 18px -9px color-mix(in oklab, var(--mk-signal, #bf2f09) 75%, #000); }
.primary:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 88%, #000); transform: translateY(-2px); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.22), 0 1px 1px rgb(0 0 0 / 0.16), 0 16px 26px -12px color-mix(in oklab, var(--mk-signal, #bf2f09) 80%, #000); }
.primary:active { transform: translateY(1px) scale(0.98); box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.22), 0 0 0 rgb(0 0 0 / 0), 0 2px 5px -3px color-mix(in oklab, var(--mk-signal, #bf2f09) 70%, #000); transition-duration: var(--mk-duration-instant, 90ms); transition-timing-function: var(--mk-ease-standard, ease); }
