/* ── Hero ──────────────────────────────────────────────────────────────── */
.hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; max-width: 1480px; margin: 0 auto; padding: clamp(28px, 6cqi, 88px) var(--tarn-pad) clamp(56px, 8cqi, 120px); }
