.heroActions { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px 24px; margin-top: 30px; }

/* Product window */
.window { position: relative; overflow: hidden; border: 1px solid color-mix(in oklab, var(--mk-ink, #11110f) 20%, transparent); border-radius: 14px; background: var(--mk-surface, #fbf9f4); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.5); font-size: 0.875rem; }
