.winDots { display: flex; gap: 5px; }
.winDots i { width: 9px; height: 9px; border-radius: 50%; background: var(--mk-ink-muted, #5c5a52); }
.winTitle { font-weight: 650; }
.winUrl { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }
.sampleTag { flex: none; padding: 2px 8px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; }
.winBody { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); }
@container (min-width: 640px) { .winBody { grid-template-columns: minmax(200px, 0.8fr) minmax(0, 2fr); } .listWrap { border-right: 1px solid var(--mk-line, #11110f24); border-bottom: 0 !important; } }
.listWrap { position: relative; border-bottom: 1px solid var(--mk-line, #11110f24); }
