}
.delivery { position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: 'st ev' 'st meta'; align-items: center; column-gap: 10px; width: 100%; min-height: 48px; padding: 7px 10px; border: 0; border-radius: 8px; background: transparent; color: var(--mk-ink, #11110f); text-align: left; cursor: pointer; transition: background-color var(--mk-duration-fast, 160ms), transform var(--press-dur, 330ms) var(--press, ease); }
.delivery:hover:not([aria-pressed='true']) { background: color-mix(in oklab, var(--mk-surface-2, #e9e5da) 70%, transparent); }
