.status[data-ok='false'] { color: var(--mk-danger, #b42318); background: color-mix(in oklab, var(--mk-danger, #b42318) 12%, transparent); }
.detail { min-width: 0; padding: 14px 16px 16px; }
.reqLine { margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.8125rem; overflow-wrap: anywhere; }
