@keyframes tarn-line { from { opacity: 0; translate: -10px 0; } }
.replayRow { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-top: 10px; }
.replayBtn { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px; border: 1.5px solid var(--mk-ink, #11110f); border-radius: 8px; background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font: 600 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; justify-self: start; box-shadow: var(--sh-rest); }
.replayBtn:hover { background: var(--mk-surface, #fbf9f4); transform: translateY(-2px); box-shadow: var(--sh-lift); }
