/* ── Sections ──────────────────────────────────────────────────────────── */
.section, .differ, .final { max-width: 1480px; margin: 0 auto; padding: clamp(64px, 9cqi, 128px) var(--tarn-pad); border-top: 1px solid var(--mk-line, #11110f24); scroll-margin-top: 104px; }
.sectionHead { max-width: 760px; margin-bottom: clamp(28px, 4cqi, 48px); }
.kicker { margin: 0 0 14px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--tarn-lake); }
.h2 { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-weight: 700; font-size: clamp(2.125rem, 1.2rem + 3cqi, 3.625rem); line-height: 1; letter-spacing: -0.045em; text-wrap: balance; }
.intro { max-width: 58ch; margin: 18px 0 0; font-size: 1.0625rem; line-height: 1.6; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }

/* How it works */
.tabs { position: relative; display: inline-flex; flex-wrap: wrap; gap: 4px; padding: 4px; border-radius: 12px; background: var(--mk-surface-2, #e9e5da); }
.tabs .ind { border-radius: 9px; background: var(--mk-surface, #fbf9f4); box-shadow: 0 1px 2px rgb(0 0 0 / 0.12), 0 0 0 1px var(--mk-line, #11110f24); }
.tab { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 9px; min-height: 44px; padding: 0 18px 0 12px; border: 0; border-radius: 9px; background: transparent; color: var(--mk-ink, #11110f); font: 600 0.9375rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; }
.tabNum { display: grid; place-items: center; width: 22px; height: 22px; border: 1px solid var(--mk-ink-muted, #5c5a52); border-radius: 50%; font: 600 0.6875rem/1 var(--mk-font-mono, ui-monospace, monospace); }
.tab[aria-selected='true'] .tabNum { border-color: var(--mk-ink, #11110f); background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); }
.panel { margin-top: 28px; }
.panelGrid { display: grid; gap: 24px; }
@container (min-width: 900px) { .panelGrid { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: 56px; align-items: start; } }
.panelTitle { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-size: 1.625rem; font-weight: 650; line-height: 1.15; letter-spacing: -0.025em; }
.panelCopy p { max-width: 50ch; margin: 12px 0 0; font-size: 1rem; line-height: 1.6; color: var(--mk-ink-muted, #5c5a52); }
.fragment { display: grid; align-content: start; gap: 10px; min-width: 0; padding: 18px; border: 1px solid var(--mk-line, #11110f24); border-radius: 14px; background: var(--mk-surface, #fbf9f4); }
