.smallBtn { justify-self: start; min-height: 44px; padding: 0 14px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 8px; background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font: 600 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; white-space: nowrap; box-shadow: var(--sh-rest); }
.smallBtn:hover { background: var(--mk-surface, #fbf9f4); transform: translateY(-2px); box-shadow: var(--sh-lift); }
.fHint { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 1.35em; margin: 0; font-size: 0.8125rem; line-height: 1.4; color: var(--mk-ink-muted, #5c5a52); }
.feed { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; }
.feed li { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 8px; background: var(--mk-bg, #f3f0e8); font-size: 0.8125rem; }
@media (prefers-reduced-motion: no-preference) { .root:not([data-reduced]) .feed li[data-new]:first-child { animation: tarn-in var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease) both; } }
@keyframes tarn-in { from { opacity: 0; transform: translateY(-8px); } }
.diff { margin: 0; padding: 12px 14px; border-radius: 8px; background: var(--mk-bg, #f3f0e8); font: 0.8125rem/1.7 var(--mk-font-mono, ui-monospace, monospace); white-space: pre-wrap; overflow-wrap: anywhere; }
.dCtx { color: var(--mk-ink-muted, #5c5a52); }
.dDel, .dAdd { padding: 1px 4px; border-radius: 3px; }
.dDel { background: color-mix(in oklab, var(--mk-success, #0a6e4d) 12%, transparent); }
.dAdd { background: color-mix(in oklab, var(--mk-danger, #b42318) 12%, transparent); }
