.targets { display: grid; gap: 6px; min-inline-size: 0; margin: 0; padding: 0; border: 0; }
.targets legend { margin-bottom: 6px; }
.target { display: flex; align-items: flex-start; gap: 10px; padding: 10px 12px; border: 1px solid var(--mk-line, #11110f24); border-radius: 10px; cursor: pointer; }
.target:has(:checked) { border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f); }
.target:has(:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
