.confirm p { margin: 0 0 10px; font-size: 0.875rem; line-height: 1.45; overflow-wrap: anywhere; }
.confirmRow { display: flex; flex-wrap: wrap; gap: 8px; }
.dangerBtn { min-height: 44px; padding: 0 14px; border: 0; border-radius: 8px; background: var(--mk-danger, #b42318); color: var(--mk-bg, #f3f0e8); font: 600 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), var(--sh-rest); }
