.compare thead th { border-bottom-color: var(--mk-ink, #11110f); font-size: 0.6875rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.compare tbody th { font-weight: 600; }
.compare td[data-changed] { background: color-mix(in oklab, var(--mk-danger, #b42318) 8%, transparent); }
.changed, .same { display: block; margin-top: 4px; font: 600 0.6875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); letter-spacing: 0.06em; text-transform: uppercase; }
