.capsTitle { max-width: 30ch; margin: 0 0 22px; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-size: 1.375rem; font-weight: 650; line-height: 1.2; letter-spacing: -0.02em; }
.capList { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); column-gap: 28px; margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--mk-ink, #11110f); }
.capList li { padding: 20px 0 24px; border-bottom: 1px solid var(--mk-line, #11110f24); }
.capList h3 { margin: 0; font-size: 1.0625rem; font-weight: 650; }
.capList p { margin: 6px 0 12px; font-size: 0.9375rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }
.capCode { font: 0.75rem/1.4 var(--mk-font-mono, ui-monospace, monospace); color: var(--tarn-lake); overflow-wrap: anywhere; }

/* Progressive reveal (content is visible unless JS marks it as waiting) */
[data-reveal='wait'].differCopy, [data-reveal='wait'].compareWrap, .capList li[data-reveal='wait'] { opacity: 0; transform: translateY(20px); }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .differCopy, .root:not([data-reduced]) .compareWrap, .root:not([data-reduced]) .capList li {
    transition: opacity var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease), transform var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease);
    transition-delay: calc(var(--i, 0) * 70ms);
  }
  .root:not([data-reduced]) .compareWrap { transition-delay: 120ms; }
}

/* Pricing */
.pricing { display: grid; gap: 28px; }
.billing { justify-self: start; min-inline-size: 0; margin: 0; padding: 0; border: 0; }
.billingTrack { position: relative; display: inline-flex; gap: 4px; padding: 4px; border-radius: 12px; background: var(--mk-surface-2, #e9e5da); }
.billingInd { border-radius: 9px; background: var(--mk-surface, #fbf9f4); box-shadow: 0 1px 2px rgb(0 0 0 / 0.12), 0 0 0 1px var(--mk-line, #11110f24); }
