@media (prefers-reduced-motion: no-preference) { .root:not([data-reduced]) .tlTick { animation: tarn-tick var(--settle-dur, 490ms) var(--settle, ease) calc(320ms + var(--i, 0) * 48ms) both; } }
@keyframes tarn-tick { from { transform: scaleY(0); } }
