.endpoint { display: inline-flex; align-items: center; gap: 6px; min-height: 28px; padding: 0 10px 0 8px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; background: var(--mk-bg, #f3f0e8); font: 600 0.75rem/1 var(--mk-font-mono, ui-monospace, monospace); box-shadow: var(--sh-rest); }
