  position: absolute; left: 0; top: 0; z-index: 5; offset-rotate: 0deg; offset-distance: 0%; opacity: 0; pointer-events: none;
  padding: 3px 8px; border-radius: 999px; background: var(--tarn-lake); color: var(--mk-bg, #f3f0e8); white-space: nowrap;
